insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_expert','expert','noun','a person with a high level of knowledge or skill in a particular subject','[{"senseId":"expert_1","meaning":"a person with a high level of knowledge or skill in a particular subject","acceptedParaphrases":["specialist","person with great knowledge"],"masteryContexts":[{"contextId":"u8_41_expert_meaning","text":"She is an expert on ancient Egypt and has written six books about it.","meaning":"a person who knows a great deal about a subject","wrongMeanings":["a person who is new to a subject","a person who dislikes a subject","a person who teaches young children"]},{"contextId":"u8_41_expert_paraphrase","text":"The insurance company sent an expert to examine the damage to the roof.","meaning":"a person with special skills and knowledge","wrongMeanings":["a person with no training","a person who sells roofs","a person who owns the house"]}],"situationDistractors":["A boy tried to fix his bike for the first time.","A new trainee asked how to use the photocopier.","A tourist asked for directions to the museum.","A child guessed the answer to a science question.","A customer read the instructions for a new phone.","A student looked up a word in the dictionary."],"gapDistractors":[{"contextId":"u8_41_expert_gap_1","answer":"expert","wrong":["minority","landscape","packaging"]},{"contextId":"u8_41_expert_gap_2","answer":"expert","wrong":["minority","assignment","technology"]},{"contextId":"u8_41_expert_gap_3","answer":"expert","wrong":["minority","landscape","technology"]}],"spellingErrors":["expurt","expirt","exspert","exprt","expertt","ekspert"],"wordFamilyForms":[{"form":"expert","partOfSpeech":"noun","example":"An expert examined the painting and said it was a copy.","pedagogicallyUseful":true},{"form":"expertise","partOfSpeech":"noun","example":"The company hired her because of her expertise in design.","pedagogicallyUseful":true,"altExample":"We need someone with expertise in solar energy."},{"form":"expertly","partOfSpeech":"adverb","example":"The chef expertly cut the vegetables into thin strips.","pedagogicallyUseful":true,"altExample":"The pilot expertly landed the plane in strong winds."}],"masteryPassages":[{"passageId":"u8_41_expert_passage_1","contextId":"u8_41_expert_gap_1","text":"Nobody in the office could work out why the computers kept crashing. In the end, the manager called an ____ who had fixed similar problems for twenty years.","answer":"expert"},{"passageId":"u8_41_expert_passage_2","contextId":"u8_41_expert_gap_2","text":"The old vase was found in a farmhouse. An ____ from the museum examined it carefully and said it was over two thousand years old.","answer":"expert"}],"contextDependentParaphrases":[],"wrongParaphrases":["beginner","customer","stranger"],"misleadingDistractors":["a beginner who is still learning","a person who is paid to sell things","a person who checks tickets"],"teacherNote":"Noun: a person with a high level of knowledge or skill in a subject (an expert in, an expert on, a computer expert). Boundary: an expert has deep knowledge; a specialist is an expert who works in one narrow area. The noun expertise and the adverb expertly are taught in the Word Family pathway."}]'::jsonb,'["expertise","expertly"]'::jsonb,'["an expert on","a leading expert","expert advice"]'::jsonb,'live'),
('vocab_engineer_8','engineer','noun','a person trained to design, build or repair machines, structures or systems','[{"senseId":"engineer_8_1","meaning":"a person trained to design, build or repair machines, structures or systems","acceptedParaphrases":["person who designs and builds machines","technical designer"],"masteryContexts":[{"contextId":"u8_42_engineer_8_meaning","text":"The engineer checked every part of the bridge before it opened to traffic.","meaning":"a person trained to design and check structures","wrongMeanings":["a person who drives across bridges","a person who paints bridges","a person who sells tickets for a bridge"]},{"contextId":"u8_42_engineer_8_paraphrase","text":"Rahul works as a software engineer, writing programs for hospitals.","meaning":"a person who designs and builds systems","wrongMeanings":["a person who repairs shoes","a person who sells phones","a person who teaches music"]}],"situationDistractors":["A waiter took an order from a customer.","A singer practised a new song.","A florist arranged roses in a vase.","A hairdresser cut a customer’s hair.","A librarian put books back on the shelves.","A cashier counted coins at the end of the day."],"gapDistractors":[{"contextId":"u8_42_engineer_8_gap_1","answer":"engineer","wrong":["nutritionist","minority","landscape"]},{"contextId":"u8_42_engineer_8_gap_2","answer":"engineer","wrong":["instructor","assignment","innovation"]},{"contextId":"u8_42_engineer_8_gap_3","answer":"engineer","wrong":["nutritionist","landscape","technology"]}],"spellingErrors":["enginer","engeneer","enginere","ingineer","enjineer","engineeer"],"masteryPassages":[{"passageId":"u8_42_engineer_8_passage_1","contextId":"u8_42_engineer_8_gap_1","text":"The new bridge has to carry thousands of cars a day and survive strong winds. An ____ spent two years calculating exactly how strong each part must be.","answer":"engineer"},{"passageId":"u8_42_engineer_8_passage_2","contextId":"u8_42_engineer_8_gap_2","text":"When the factory’s main machine broke down, production stopped completely. The company called an ____, who found the fault and repaired it by lunchtime.","answer":"engineer"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who sells and delivers machines","person who buys and uses machines","person who cleans and stores machines"],"misleadingDistractors":["a person who sells cars","a person who draws pictures for books","a person who cleans offices"],"teacherNote":"Noun: a person trained to design, build or repair machines, structures or systems (a civil engineer, a software engineer). Unit 8 uses it as a job title in the world of work; Unit 4 taught the same core sense. No family is taught: engineering (the subject) is the only other common form."}]'::jsonb,'[]'::jsonb,'["a civil engineer","a software engineer","a qualified engineer"]'::jsonb,'live'),
('vocab_scientist','scientist','noun','a person who studies the natural world through experiments and observation','[{"senseId":"scientist_1","meaning":"a person who studies the natural world through experiments and observation","acceptedParaphrases":["researcher","person who studies nature by experiment"],"masteryContexts":[{"contextId":"u8_43_scientist_meaning","text":"The scientist tested the water every day to see how much plastic it contained.","meaning":"a person who studies things through experiments","wrongMeanings":["a person who sells bottled water","a person who cleans rivers","a person who designs boats"]},{"contextId":"u8_43_scientist_paraphrase","text":"A scientist working in the rainforest has discovered a new type of frog.","meaning":"a researcher who studies nature","wrongMeanings":["a tourist who visits places","a farmer who grows crops","an artist who paints scenes"]}],"situationDistractors":["An actor learned his lines for a play.","A shop assistant folded T-shirts.","A bus driver stopped to let passengers on.","A poet read her work at a café.","A tailor measured a customer for a suit.","A footballer practised taking penalties."],"gapDistractors":[{"contextId":"u8_43_scientist_gap_1","answer":"scientist","wrong":["landscape","minority","packaging"]},{"contextId":"u8_43_scientist_gap_2","answer":"scientist","wrong":["landscape","minority","director"]},{"contextId":"u8_43_scientist_gap_3","answer":"scientist","wrong":["landscape","technology","director"]}],"spellingErrors":["sientist","scientest","scintist","sceintist","scientis","scienctist"],"wordFamilyForms":[{"form":"scientist","partOfSpeech":"noun","example":"The scientist explained her research to the students.","pedagogicallyUseful":true},{"form":"science","partOfSpeech":"noun","example":"He wants to study science at university.","pedagogicallyUseful":true,"altExample":"Computer science is a popular course."},{"form":"scientific","partOfSpeech":"adjective","example":"The company carried out scientific tests on the new cream.","pedagogicallyUseful":true,"altExample":"There is no scientific evidence that the drink improves memory."}],"masteryPassages":[{"passageId":"u8_43_scientist_passage_1","contextId":"u8_43_scientist_gap_1","text":"In the laboratory, a young ____ mixed two chemicals and watched carefully. She wrote down every change in colour and temperature.","answer":"scientist"},{"passageId":"u8_43_scientist_passage_2","contextId":"u8_43_scientist_gap_2","text":"For years, people did not know why the bees were dying. Then a ____ at the university carried out experiments and discovered that a chemical used on farms was to blame.","answer":"scientist"}],"contextDependentParaphrases":[],"wrongParaphrases":["reporter","retailer","receptionist"],"misleadingDistractors":["a person who writes stories","a person who manages a shop","a person who sells medicines"],"teacherNote":"Noun: a person who studies the natural world through experiments and observation (a research scientist, a team of scientists). Boundary: a scientist researches and discovers; an engineer uses scientific knowledge to design and build. The noun science and the adjective scientific are taught in the Word Family pathway."}]'::jsonb,'["science","scientific"]'::jsonb,'["a research scientist","a team of scientists","a leading scientist"]'::jsonb,'live'),
('vocab_assignment','assignment','noun','a piece of work or a task that someone is given as part of their job or studies','[{"senseId":"assignment_1","meaning":"a piece of work or a task that someone is given as part of their job or studies","acceptedParaphrases":["task given to someone","piece of set work"],"masteryContexts":[{"contextId":"u8_44_assignment_meaning","text":"The manager gave Leo his first assignment: to write a report on the competition.","meaning":"a task given at work","wrongMeanings":["a reward given at work","a desk given at work","a uniform given at work"]},{"contextId":"u8_44_assignment_paraphrase","text":"Students must finish the history assignment before the end of term.","meaning":"a piece of work set by a teacher","wrongMeanings":["a test taken without warning","a trip outside school","a book given as a prize"]}],"situationDistractors":["A worker relaxed on a beach during her holiday.","A student chose a novel to read for fun.","A manager went home early because she felt ill.","Two colleagues chatted about football at lunch.","A trainee waited in reception for a meeting.","A cleaner finished her shift and went home."],"gapDistractors":[{"contextId":"u8_44_assignment_gap_1","answer":"assignment","wrong":["minority","landscape","humanity"]},{"contextId":"u8_44_assignment_gap_2","answer":"assignment","wrong":["minority","humanity","technology"]},{"contextId":"u8_44_assignment_gap_3","answer":"assignment","wrong":["minority","landscape","humanity"]}],"spellingErrors":["assigment","asignment","assignmant","assinement","assignmint","asignmant"],"masteryPassages":[{"passageId":"u8_44_assignment_passage_1","contextId":"u8_44_assignment_gap_1","text":"The teacher gave the class two weeks to write an essay about a job they would like. Ravi finished his ____ early and handed it in on Monday.","answer":"assignment"},{"passageId":"u8_44_assignment_passage_2","contextId":"u8_44_assignment_gap_2","text":"The newspaper sent its best reporter to cover the election. It was her most difficult ____ so far, but she sent back an excellent story.","answer":"assignment"}],"contextDependentParaphrases":[],"wrongParaphrases":["prize given to someone","day off for someone","gift sent to someone"],"misleadingDistractors":["a meeting to discuss pay","a prize for excellent work","a holiday from work"],"teacherNote":"Noun: a piece of work or a task given to someone as part of their job or studies (a written assignment, on assignment). Boundary: an assignment is given to you by someone else; a project can be your own idea. The verb assign is the only other useful form, so no family is taught."}]'::jsonb,'[]'::jsonb,'["a written assignment","complete an assignment","hand in an assignment"]'::jsonb,'live'),
('vocab_employment','employment','noun','the state of having paid work, or the work that people do for money','[{"senseId":"employment_1","meaning":"the state of having paid work, or the work that people do for money","acceptedParaphrases":["paid work","having a job"],"masteryContexts":[{"contextId":"u8_45_employment_meaning","text":"After leaving university, Mira found employment with a large engineering company.","meaning":"paid work","wrongMeanings":["free training","a long holiday","a student loan"]},{"contextId":"u8_45_employment_paraphrase","text":"Since the mine closed, employment in the town has fallen sharply.","meaning":"the number of people with jobs","wrongMeanings":["the number of people on holiday","the number of new houses","the number of tourists"]}],"situationDistractors":["A retired teacher spent the day in her garden.","A child played computer games after school.","A tourist relaxed by the hotel pool.","A student read a book in the library for fun.","A grandfather walked his dog in the park.","Two friends went shopping on Saturday."],"gapDistractors":[{"contextId":"u8_45_employment_gap_1","answer":"employment","wrong":["packaging","architecture","minority"]},{"contextId":"u8_45_employment_gap_2","answer":"employment","wrong":["packaging","architecture","humanity"]},{"contextId":"u8_45_employment_gap_3","answer":"employment","wrong":["packaging","architecture","landscape"]}],"spellingErrors":["employmant","imployment","employement","emploiment","emplyment","employmment"],"wordFamilyForms":[{"form":"employment","partOfSpeech":"noun","example":"The new hotel will bring employment to the village.","pedagogicallyUseful":true},{"form":"employ","partOfSpeech":"verb","example":"The company plans to employ fifty new staff next year.","pedagogicallyUseful":true,"altExample":"Small businesses employ most of the workers in the region."},{"form":"unemployed","partOfSpeech":"adjective","example":"He has been unemployed since the shop closed in March.","pedagogicallyUseful":true,"altExample":"The course helps unemployed people learn new skills."}],"masteryPassages":[{"passageId":"u8_45_employment_passage_1","contextId":"u8_45_employment_gap_1","text":"When the car factory closed, many workers spent months looking for new jobs. Some found ____ in the new supermarket, but others had to move to the city.","answer":"employment"},{"passageId":"u8_45_employment_passage_2","contextId":"u8_45_employment_gap_2","text":"The town council wants young people to stay in the area. It is offering money to companies that create ____ for school leavers.","answer":"employment"}],"contextDependentParaphrases":[],"wrongParaphrases":["free time","unpaid leave","school holidays"],"misleadingDistractors":["time spent on holiday","money given to a charity","training done for free"],"teacherNote":"Noun: having paid work, or the work people do (find employment, full-time employment, employment law). Boundary: employment is a formal word for having a job; a job is one particular position. The verb employ and the adjective unemployed are taught in the Word Family pathway."}]'::jsonb,'["employ","unemployed"]'::jsonb,'["full-time employment","find employment","employment opportunities"]'::jsonb,'live'),
('vocab_traditional','traditional','adjective','following customs, methods or beliefs that have existed for a long time','[{"senseId":"traditional_1","meaning":"following customs, methods or beliefs that have existed for a long time","acceptedParaphrases":["customary and long-established","done in the same way for many years"],"masteryContexts":[{"contextId":"u8_46_traditional_meaning","text":"The furniture is made by hand using traditional tools that have not changed for centuries.","meaning":"used in the same way for a very long time","wrongMeanings":["invented only last year","bought from a modern factory","controlled by a computer"]},{"contextId":"u8_46_traditional_paraphrase","text":"Many young people are leaving traditional jobs such as farming and fishing.","meaning":"old and long-established","wrongMeanings":["new and highly paid","rare and secret","temporary and part-time"]}],"situationDistractors":["A start-up used artificial intelligence to design a new shoe.","A designer tried a completely new way of building houses from plastic.","A café created a dish that nobody had ever tasted before.","A company launched an app that did not exist last year.","An engineer tested a robot that cooks dinner.","A fashion brand used a new fabric made from mushrooms."],"gapDistractors":[{"contextId":"u8_46_traditional_gap_1","answer":"traditional","wrong":["relentless","responsible","rough"]},{"contextId":"u8_46_traditional_gap_2","answer":"traditional","wrong":["relentless","rough","responsible"]},{"contextId":"u8_46_traditional_gap_3","answer":"traditional","wrong":["relentless","responsible","significant"]}],"spellingErrors":["tradicional","traditonal","tradditional","traditionnal","tradtional","traditinal"],"wordFamilyForms":[{"form":"traditional","partOfSpeech":"adjective","example":"The village is famous for its traditional pottery.","pedagogicallyUseful":true},{"form":"tradition","partOfSpeech":"noun","example":"It is a tradition in the company to have lunch together on Fridays.","pedagogicallyUseful":true,"altExample":"The festival is an old tradition in this part of Spain."},{"form":"traditionally","partOfSpeech":"adverb","example":"Fishing has traditionally been the main job on the island.","pedagogicallyUseful":true,"altExample":"In many countries, the bride has traditionally worn white."}],"masteryPassages":[{"passageId":"u8_46_traditional_passage_1","contextId":"u8_46_traditional_gap_1","text":"In the small factory, every rug is still woven by hand, exactly as it was two hundred years ago. The owners say that these ____ methods give the rugs their special quality.","answer":"traditional"},{"passageId":"u8_46_traditional_passage_2","contextId":"u8_46_traditional_gap_2","text":"At the wedding, the guests danced the same dances and ate the same food as their grandparents had. Everything about the celebration was ____.","answer":"traditional"}],"contextDependentParaphrases":[],"wrongParaphrases":["brand-new and experimental","foreign and unusual","cheap and mass-produced"],"misleadingDistractors":["completely new and modern","done only once by chance","copied recently from another country"],"teacherNote":"Adjective: following customs or methods used for a long time (traditional methods, traditional food, traditional crafts). Boundary: traditional is neutral or positive; old-fashioned often suggests something is out of date. The noun tradition and the adverb traditionally are taught in the Word Family pathway."}]'::jsonb,'["tradition","traditionally"]'::jsonb,'["traditional methods","traditional food","a traditional craft"]'::jsonb,'live'),
('vocab_trainer','trainer','noun','a person whose job is to teach skills to workers or athletes and help them improve','[{"senseId":"trainer_1","meaning":"a person whose job is to teach skills to workers or athletes and help them improve","acceptedParaphrases":["coach","person who trains others"],"masteryContexts":[{"contextId":"u8_47_trainer_meaning","text":"A personal trainer helped Maria get fit for the marathon.","meaning":"a person who coaches someone to improve their fitness","wrongMeanings":["a person who sells running shoes","a person who organises races","a person who treats injuries"]},{"contextId":"u8_47_trainer_paraphrase","text":"The IT trainer spent the morning showing staff how to use the new software.","meaning":"a person who teaches work skills","wrongMeanings":["a person who repairs computers","a person who sells software","a person who writes programs"]}],"situationDistractors":["A shop assistant sold a pair of running shoes.","A customer joined a gym and paid the fee.","A runner trained alone in the park at dawn.","A receptionist booked a meeting room.","A manager read an email about sales.","A cleaner mopped the floor of the gym."],"gapDistractors":[{"contextId":"u8_47_trainer_gap_1","answer":"trainer","wrong":["landscape","minority","technology"]},{"contextId":"u8_47_trainer_gap_2","answer":"trainer","wrong":["landscape","technology","packaging"]},{"contextId":"u8_47_trainer_gap_3","answer":"trainer","wrong":["landscape","minority","technology"]}],"spellingErrors":["trainor","traner","trainner","trayner","traineer","triner"],"wordFamilyForms":[{"form":"trainer","partOfSpeech":"noun","example":"The trainer showed the new staff how to use the coffee machine.","pedagogicallyUseful":true},{"form":"train","partOfSpeech":"verb","example":"The company will train you to use all the equipment.","pedagogicallyUseful":true,"altExample":"It takes years to train a pilot."},{"form":"trainee","partOfSpeech":"noun","example":"Each trainee works with an experienced chef for six months.","pedagogicallyUseful":true,"altExample":"The trainee made a few mistakes on her first day."}],"masteryPassages":[{"passageId":"u8_47_trainer_passage_1","contextId":"u8_47_trainer_gap_1","text":"Every new employee at the hotel spends three days on a course. A ____ shows them how to welcome guests, answer the phone and deal with complaints.","answer":"trainer"},{"passageId":"u8_47_trainer_passage_2","contextId":"u8_47_trainer_gap_2","text":"Sam wanted to get fit before the summer, so he joined a gym. His ____ planned his exercises and pushed him to work harder each week.","answer":"trainer"}],"contextDependentParaphrases":[],"wrongParaphrases":["referee","spectator","sponsor"],"misleadingDistractors":["a person who builds machines","a person who checks safety rules","a person who manages a shop"],"teacherNote":"Noun: a person who teaches skills to workers or athletes and helps them improve (a personal trainer, a staff trainer). Boundary: trainers can also mean sports shoes, and an instructor usually teaches a practical activity such as driving. The verb train and the noun trainee are taught in the Word Family pathway."}]'::jsonb,'["train","trainee"]'::jsonb,'["a personal trainer","a fitness trainer","a staff trainer"]'::jsonb,'live'),
('vocab_technology','technology','noun','scientific knowledge used to make machines, equipment and systems that solve practical problems','[{"senseId":"technology_1","meaning":"scientific knowledge used to make machines, equipment and systems that solve practical problems","acceptedParaphrases":["modern machines and equipment","science used in practical ways"],"masteryContexts":[{"contextId":"u8_48_technology_meaning","text":"Farmers now use technology such as drones to check their crops.","meaning":"machines and equipment based on science","wrongMeanings":["old methods passed down in families","money borrowed from banks","rules made by the government"]},{"contextId":"u8_48_technology_paraphrase","text":"Information technology is the fastest-growing area of employment in the city.","meaning":"the use of computers and electronic systems","wrongMeanings":["the use of hand tools","the use of farm animals","the use of printed books"]}],"situationDistractors":["A farmer ploughed his field with two horses.","A woman wrote a letter by hand with a pen.","A carpenter cut wood with a hand saw.","A child counted on her fingers.","A baker kneaded dough by hand.","A shepherd walked his sheep to market."],"gapDistractors":[{"contextId":"u8_48_technology_gap_1","answer":"technology","wrong":["landscape","minority","packaging"]},{"contextId":"u8_48_technology_gap_2","answer":"technology","wrong":["landscape","minority","humanity"]},{"contextId":"u8_48_technology_gap_3","answer":"technology","wrong":["landscape","minority","humanity"]}],"spellingErrors":["tecnology","technolgy","tecknology","technologie","techology","technollogy"],"wordFamilyForms":[{"form":"technology","partOfSpeech":"noun","example":"Modern technology has changed the way we communicate.","pedagogicallyUseful":true},{"form":"technological","partOfSpeech":"adjective","example":"The company is famous for its technological innovations.","pedagogicallyUseful":true,"altExample":"Every year brings new technological changes to the workplace."},{"form":"technologically","partOfSpeech":"adverb","example":"It is a technologically advanced factory with very few workers.","pedagogicallyUseful":true,"altExample":"Japan is one of the most technologically advanced countries in the world."}],"masteryPassages":[{"passageId":"u8_48_technology_passage_1","contextId":"u8_48_technology_gap_1","text":"Twenty years ago, the factory needed two hundred workers. Now robots and computers do most of the jobs, and new ____ is added every year.","answer":"technology"},{"passageId":"u8_48_technology_passage_2","contextId":"u8_48_technology_gap_2","text":"In the past, students had to visit a library to find information. Today, thanks to ____, they can search millions of books on a phone in seconds.","answer":"technology"}],"contextDependentParaphrases":[],"wrongParaphrases":["old customs and beliefs","natural plants and animals","local shops and markets"],"misleadingDistractors":["the study of plants and animals","the history of how people lived","the rules for running a business"],"teacherNote":"Noun: scientific knowledge used to make machines, equipment and systems (new technology, information technology). Boundary: technology is the practical use of knowledge and the equipment it produces; science is the study that discovers how things work. The adjective technological and the adverb technologically are taught in the Word Family pathway."}]'::jsonb,'["technological","technologically"]'::jsonb,'["new technology","information technology","the latest technology"]'::jsonb,'live'),
('vocab_creative','creative','adjective','good at thinking of new and original ideas or at making new things','[{"senseId":"creative_1","meaning":"good at thinking of new and original ideas or at making new things","acceptedParaphrases":["imaginative","full of original ideas"],"masteryContexts":[{"contextId":"u8_49_creative_meaning","text":"Lena is very creative and has designed all the posters for the school play.","meaning":"good at producing original ideas","wrongMeanings":["good at following instructions","good at counting money","good at keeping secrets"]},{"contextId":"u8_49_creative_paraphrase","text":"Jobs in the creative industries, such as film and design, are popular with young people.","meaning":"producing art and new ideas","wrongMeanings":["producing food and drink","producing cars and machines","producing oil and gas"]}],"situationDistractors":["A clerk copied numbers from one form to another.","A worker followed the same checklist every morning.","A student copied an answer from the textbook.","A cashier counted the coins in the till.","A driver followed the same route every day.","A typist copied a letter word for word."],"gapDistractors":[{"contextId":"u8_49_creative_gap_1","answer":"creative","wrong":["relentless","responsible","curved"]},{"contextId":"u8_49_creative_gap_2","answer":"creative","wrong":["relentless","curved","qualified"]},{"contextId":"u8_49_creative_gap_3","answer":"creative","wrong":["relentless","responsible","sustainable"]}],"spellingErrors":["creatieve","criative","creetive","creativ","craetive","creattive"],"wordFamilyForms":[{"form":"creative","partOfSpeech":"adjective","example":"The job needs a creative person who can design new logos.","pedagogicallyUseful":true},{"form":"create","partOfSpeech":"verb","example":"The new factory will create two hundred jobs.","pedagogicallyUseful":true,"altExample":"The designers want to create a chair that folds flat."},{"form":"creativity","partOfSpeech":"noun","example":"The teacher praised the creativity of the students’ designs.","pedagogicallyUseful":true,"altExample":"The company rewards creativity as well as hard work."}],"masteryPassages":[{"passageId":"u8_49_creative_passage_1","contextId":"u8_49_creative_gap_1","text":"Most people use plastic bottles once and throw them away. Ayo, however, turned hundreds of them into a colourful garden wall. She is one of the most ____ people I know.","answer":"creative"},{"passageId":"u8_49_creative_passage_2","contextId":"u8_49_creative_gap_2","text":"The advertising company does not want staff who simply copy what others have done. It is looking for ____ designers who can think of ideas nobody has seen before.","answer":"creative"}],"contextDependentParaphrases":[],"wrongParaphrases":["obedient","forgetful","careless"],"misleadingDistractors":["careful to follow every rule","good at remembering facts","able to work very quickly"],"teacherNote":"Adjective: good at thinking of new, original ideas or at making new things (creative thinking, the creative industries). Boundary: creative is about producing new ideas; clever is about understanding quickly. The verb create and the noun creativity are taught in the Word Family pathway."}]'::jsonb,'["create","creativity"]'::jsonb,'["creative thinking","the creative industries","creative ideas"]'::jsonb,'live'),
('vocab_wellbeing','wellbeing','noun','the state of feeling healthy, comfortable and happy','[{"senseId":"wellbeing_1","meaning":"the state of feeling healthy, comfortable and happy","acceptedParaphrases":["health and happiness","feeling well and content"],"masteryContexts":[{"contextId":"u8_50_wellbeing_meaning","text":"Doctors say that regular breaks are important for the wellbeing of office workers.","meaning":"feeling healthy and happy","wrongMeanings":["earning a high salary","finishing work quickly","getting a promotion"]},{"contextId":"u8_50_wellbeing_paraphrase","text":"The school has a wellbeing room where students can go if they feel stressed.","meaning":"feeling calm and well","wrongMeanings":["passing exams","playing sports","saving money"]}],"situationDistractors":["A manager checked the sales figures for the month.","A worker counted boxes in the warehouse.","A director signed a contract with a new supplier.","A clerk filed invoices in alphabetical order.","An engineer measured the length of a beam.","A driver filled the van with petrol."],"gapDistractors":[{"contextId":"u8_50_wellbeing_gap_1","answer":"wellbeing","wrong":["packaging","minority","technology"]},{"contextId":"u8_50_wellbeing_gap_2","answer":"wellbeing","wrong":["packaging","architecture","minority"]},{"contextId":"u8_50_wellbeing_gap_3","answer":"wellbeing","wrong":["packaging","minority","publicity"]}],"spellingErrors":["welbeing","wellbeeing","wellbing","wellbieng","whellbeing","wellbein"],"masteryPassages":[{"passageId":"u8_50_wellbeing_passage_1","contextId":"u8_50_wellbeing_gap_1","text":"The company noticed that many workers were stressed and often ill. It introduced shorter hours, free fruit and a quiet room to improve their ____.","answer":"wellbeing"},{"passageId":"u8_50_wellbeing_passage_2","contextId":"u8_50_wellbeing_gap_2","text":"Doctors say that sleep, exercise and time with friends all affect our ____. Without them, we feel tired, unhappy and unwell.","answer":"wellbeing"}],"contextDependentParaphrases":[],"wrongParaphrases":["wealth and success","speed and accuracy","skills and training"],"misleadingDistractors":["the amount of money a person earns","the number of hours a person works","the skills a person has learned"],"teacherNote":"Noun: the state of feeling healthy, comfortable and happy (staff wellbeing, mental wellbeing). The coursebook spelling wellbeing is the accepted answer. Boundary: wellbeing includes mind and body together; health can refer only to the body. No family is taught."}]'::jsonb,'[]'::jsonb,'["staff wellbeing","mental wellbeing","a sense of wellbeing"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
